// Stage 3 — Input Validation. Refuse to continue on anything unexpected.
const body = $input.first().json;
const items = body.items || [];
if (!items.length) {
  throw new Error('Channel returned no items. Wrong ID, or key not authorized for YouTube Data API v3.');
}
const ch = items[0];
const uploads = ch?.contentDetails?.relatedPlaylists?.uploads;
if (!uploads) throw new Error('No uploads playlist on channel payload.');
const s = ch.statistics || {};
// Absent means unknown. Never coerce to 0 - a channel hiding likes is not zero likes.
const num = (v) => (v === undefined || v === null ? null : Number(v));
return [{ json: {
  uploadsPlaylistId: uploads,
  channel: {
    subscribers: s.hiddenSubscriberCount ? null : num(s.subscriberCount),
    subscribers_hidden: !!s.hiddenSubscriberCount,
    total_views: num(s.viewCount),
    video_count: num(s.videoCount)
  }
}}];

// Stage 4 — Business Logic. Collect IDs, batch by 50 for videos.list.
const ids = [];
for (const item of $input.all()) {
  const list = item.json.items || [];
  for (const i of list) {
    const id = i?.contentDetails?.videoId;
    if (id) ids.push(id);
  }
}
if (!ids.length) throw new Error('Uploads playlist empty - unexpected for this channel.');
const unique = [...new Set(ids)];
if (unique.length !== ids.length) throw new Error('Duplicate video IDs from playlist; refusing a corrupt pull.');
const batches = [];
for (let i = 0; i < unique.length; i += 50) {
  batches.push({ json: { ids: unique.slice(i, i + 50).join(','), requestedCount: unique.length } });
}
return batches;

// Stage 5/6 — Normalization and Result Validation.
const num = (v) => (v === undefined || v === null ? null : Number(v));
const videos = [];
let requested = 0;
for (const item of $input.all()) {
  requested = item.json.requestedCount || requested;
  for (const v of (item.json.items || [])) {
    const st = v.statistics || {}, sn = v.snippet || {};
    videos.push({
      video_id: v.id,
      title: sn.title || null,
      published_at: sn.publishedAt || null,
      duration: v.contentDetails?.duration || null,
      view_count: num(st.viewCount),
      like_count: num(st.likeCount),
      comment_count: num(st.commentCount),
      narratives: [],
      layer: null,
      tier: 'measured'
    });
  }
}

// Reconciliation invariant: nothing invented, nothing silently dropped.
const ids = videos.map(v => v.video_id);
if (new Set(ids).size !== ids.length) throw new Error('Duplicate video_id in results.');
if (requested && videos.length !== requested) {
  throw new Error(`Reconciliation failed: requested ${requested}, got ${videos.length}. Refusing a partial pull.`);
}
for (const v of videos) {
  if (!v.title) throw new Error(`Missing title on ${v.video_id}`);
  if (v.view_count !== null && v.view_count < 0) throw new Error(`Negative view_count on ${v.video_id}`);
}

const now = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
const date = now.slice(0, 10);
const doc = {
  schema_version: 2,
  date,
  scraped_at: now,
  data_status: 'measured',
  collection: {
    method: 'youtube_data_api_v3',
    channel_id: 'UCs5IFXnrKliqRA6U4o_VD2Q',
    handle: '@TelcoinTAO',
    coverage: 'census',
    workflow: 'PROD-YOUTUBE-ChannelStats-Pull-v1.0',
    notes: 'Full uploads playlist. Platform-reported figures, not a sample.'
  },
  channel: $('Validate Channel').first().json.channel,
  videos,
  _ingested_at: now,
  _source_system: 'youtube_data_api_v3'
};
return [{ json: { doc, date, path: `campaign/analytics/youtube/${date}.json`,
  summary: `${videos.length} videos, ${videos.reduce((a, v) => a + (v.view_count || 0), 0)} total views` } }];

// Stages 8 & 9 — Error Branch and Manual Recovery.
// Reached when any upstream node fails. Writes NOTHING to the repo.
// A missing day is recoverable; a day of zeros in the trend line is not.
const e = $input.first().json;
const msg = e.error?.message || e.message || JSON.stringify(e).slice(0, 400);
let cause = 'unknown';
if (/quota/i.test(msg)) cause = 'QUOTA_EXCEEDED - resets 00:00 PT';
else if (/403/.test(msg)) cause = 'FORBIDDEN - key not authorized for YouTube Data API v3';
else if (/400/.test(msg)) cause = 'BAD_REQUEST - check the API key is valid';
else if (/Reconciliation/i.test(msg)) cause = 'RECONCILIATION_FAILED - partial pull refused';
else if (/timeout|ETIMEDOUT|ENOTFOUND/i.test(msg)) cause = 'NETWORK';
return [{ json: {
  workflow: 'PROD-YOUTUBE-ChannelStats-Pull-v1.0',
  executed_at: new Date().toISOString(),
  source_system: 'youtube_data_api_v3',
  status: 'FAILED',
  error_class: cause,
  cause_note: msg,
  wrote_data: false,
  manual_recovery: 'Run `python3 scripts/youtube-pull.py` locally once the cause is cleared. It performs the same pull with the same guards.'
}}];
